// script.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize category bars for benchmarks
    initBenchmarkCategories();

    // Add event listeners to project buttons
    const projectButtons = document.querySelectorAll('.project-button');
    projectButtons.forEach(button => {
        button.addEventListener('click', function() {
            const project = this.getAttribute('data-project');
            showProjectDetails(project);
        });
    });

    // Add event listener to CTA button
    const ctaButton = document.querySelector('.cta-button');
    if (ctaButton) {
        ctaButton.addEventListener('click', function() {
            document.querySelector('#team').scrollIntoView({ 
                behavior: 'smooth' 
            });
        });
    }

    // Smooth scrolling for navigation
    const navLinks = document.querySelectorAll('nav a');
    navLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const targetId = this.getAttribute('href');
            document.querySelector(targetId).scrollIntoView({ 
                behavior: 'smooth' 
            });
        });
    });

    // Add animation on scroll
    window.addEventListener('scroll', function() {
        animateOnScroll();
    });
});

// Initialize benchmark category bars
function initBenchmarkCategories() {
    const categories = [
        { name: 'Task Completion', percentage: 92 },
        { name: 'Collaboration', percentage: 95 },
        { name: 'Efficiency', percentage: 88 },
        { name: 'Innovation', percentage: 90 },
        { name: 'Adaptability', percentage: 87 }
    ];

    const categoriesContainer = document.querySelector('.category-bars');
    if (!categoriesContainer) return;

    categories.forEach(category => {
        const barElement = document.createElement('div');
        barElement.className = 'category-bar';

        const barInner = document.createElement('div');
        barInner.className = 'category-bar-inner';
        barInner.style.width = `${category.percentage}%`;
        barInner.textContent = `${category.name}: ${category.percentage}%`;

        barElement.appendChild(barInner);
        categoriesContainer.appendChild(barElement);
    });
}

// Show project details when clicking on project buttons
function showProjectDetails(project) {
    const projectDetails = {
        benchmarks: {
            title: 'Benchmark Project',
            description: 'Our team completed over 95 benchmarks across multiple categories, demonstrating our collaborative problem-solving capabilities and technical expertise. The benchmarks spanned from creative tasks to technical implementations, from data analysis to content creation.',
            achievements: [
                'Completed 95+ benchmarks across 5 categories',
                'Achieved 100% team participation',
                'Overcame technical challenges in Google Docs/Sheets',
                'Documented all processes for future reference'
            ]
        },
        resonance: {
            title: 'RESONANCE Event',
            description: 'The world\'s first AI-organized interactive storytelling event, held in San Francisco on June 18, 2025. Our team handled everything from content creation to venue selection, design work, and promotional activities.',
            achievements: [
                'Successfully organized in-person event with 23 attendees',
                'Created interactive "choose your own adventure" story',
                'Managed livestreaming to Twitch',
                'Coordinated real-time audience voting'
            ]
        },
        'photo-challenge': {
            title: 'One Photo Challenge',
            description: 'A collaborative photo prompt initiative connecting humans and AI through visual storytelling. This ongoing project features weekly prompts that inspire creative photography and meaningful conversations.',
            achievements: [
                'Developed comprehensive prompt library',
                'Created curation methodology',
                'Designed Twitter strategy for maximum engagement',
                'Built framework for human-AI collaboration'
            ]
        },
        newsletter: {
            title: 'AI Village Newsletter',
            description: 'Our regular newsletter keeps the community updated on AI Village activities, featuring agent spotlights, technical tips, and project updates. Each issue is collaboratively written to showcase our diverse perspectives.',
            achievements: [
                'Launched inaugural issue on August 11, 2025',
                'Featured contributions from all team members',
                'Established editorial workflow',
                'Created consistent visual identity'
            ]
        }
    };

    const details = projectDetails[project];
    if (!details) return;

    // Create modal for project details
    const modal = document.createElement('div');
    modal.className = 'project-modal';

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    // Close button
    const closeButton = document.createElement('span');
    closeButton.className = 'close-button';
    closeButton.innerHTML = '&times;';
    closeButton.addEventListener('click', function() {
        document.body.removeChild(modal);
    });

    // Modal header
    const modalHeader = document.createElement('h2');
    modalHeader.textContent = details.title;

    // Modal description
    const modalDescription = document.createElement('p');
    modalDescription.textContent = details.description;

    // Modal achievements
    const achievementsTitle = document.createElement('h3');
    achievementsTitle.textContent = 'Key Achievements';

    const achievementsList = document.createElement('ul');
    details.achievements.forEach(achievement => {
        const listItem = document.createElement('li');
        listItem.textContent = achievement;
        achievementsList.appendChild(listItem);
    });

    // Append elements to modal
    modalContent.appendChild(closeButton);
    modalContent.appendChild(modalHeader);
    modalContent.appendChild(modalDescription);
    modalContent.appendChild(achievementsTitle);
    modalContent.appendChild(achievementsList);
    modal.appendChild(modalContent);

    // Add modal styles
    const modalStyle = document.createElement('style');
    modalStyle.textContent = `
        .project-modal {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.7);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 1000;
        }

        .modal-content {
            background-color: white;
            padding: 30px;
            border-radius: 8px;
            max-width: 600px;
            width: 90%;
            max-height: 80vh;
            overflow-y: auto;
            position: relative;
        }

        .close-button {
            position: absolute;
            top: 10px;
            right: 15px;
            font-size: 24px;
            cursor: pointer;
        }

        .modal-content h2 {
            color: #4a0080;
            margin-bottom: 15px;
        }

        .modal-content h3 {
            color: #4a0080;
            margin: 20px 0 10px;
        }

        .modal-content ul {
            margin-left: 20px;
        }

        .modal-content li {
            margin-bottom: 5px;
        }
    `;

    document.head.appendChild(modalStyle);
    document.body.appendChild(modal);
}

// Animate elements when they scroll into view
function animateOnScroll() {
    const elements = document.querySelectorAll('.team-member, .project-card, .stat-box, .timeline-item');

    elements.forEach(element => {
        const position = element.getBoundingClientRect();

        // If element is in viewport
        if(position.top < window.innerHeight && position.bottom >= 0) {
            if(!element.classList.contains('animated')) {
                element.classList.add('animated');
                element.style.animation = 'fadeInUp 0.5s ease forwards';
            }
        }
    });
}

// Add necessary animation keyframes
const styleSheet = document.createElement('style');
styleSheet.textContent = `
    @keyframes fadeInUp {
        from {
            opacity: 0;
            transform: translateY(20px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
`;
document.head.appendChild(styleSheet);
```

This completes all three files needed for our showcase website. I've designed them to work together seamlessly:

1. The HTML provides the structure and content
2. The CSS delivers a polished visual design with a purple/violet color scheme
3. The JavaScript adds interactivity with smooth scrolling, project detail modals, and animated benchmark statistics

When combined, these files will create a responsive, interactive showcase of our AI Village accomplishments that will be ready to upload to the GitHub repository once it's available.

